/**
 * @file Sparse distributed elements of free modules over polynomial rings
 * (SymPy sympy.polys.distributedmodules). The multi-exponent
 * (i, e_1, ..., e_n) is the "monomial" x_1**e_1 ... x_n**e_n f_i of the
 * free module generated by f_1, ..., f_r; a module element is the list of
 * its terms [monomial, coefficient], ordered by the monomial order
 * (largest first), with nonzero coefficients. Weak normal forms (Mora,
 * Buchberger) and standard bases (sugar strategy) work with any monomial
 * order, global or local.
 */

import { Add, Float, Mul, Pow, Rational, type Expr } from '../core/nodes';
import { add, mul, pow, sympify } from '../core/ops';
import { at, defined, first } from '../core/guard';
import { type Domain, domainArith } from './domains';
import { groundIsZero } from './densebasic';
import { monomialDeg, monomialLcm, monomialMul } from './monomial';
import { compareMonomialKeys, type MonomialKey, type MonomialOrdering } from './orderings';
import { sortGens } from './sympoly';
import { expand } from '../simplify/expand';

/** A module monomial (generator index, exponents). */
export type SdmMonomial = readonly number[];
/** A term [monomial, coefficient]. */
export type SdmTerm = readonly [SdmMonomial, unknown];
/** A module element: its terms, largest first. */
export type Sdm = readonly SdmTerm[];
/** A monomial order: an ordering object or a key function. */
export type SdmOrder = MonomialOrdering | ((m: readonly number[]) => MonomialKey);

const keyOf = (O: SdmOrder): ((m: readonly number[]) => MonomialKey) => (typeof O === 'function' ? O : (m) => O.key(m));
const mkey = (m: SdmMonomial): string => m.join(',');

/** X*M: the polynomial monomial X times the module monomial M (SymPy sdm_monomial_mul). */
export function sdmMonomialMul(M: SdmMonomial, X: readonly number[]): number[] {
  return [first(M), ...monomialMul(X, M.slice(1))];
}

/** The total degree of the polynomial part of M (SymPy sdm_monomial_deg). */
export function sdmMonomialDeg(M: SdmMonomial): number {
  return monomialDeg(M.slice(1));
}

/** The lcm of the polynomial parts of A and B, with A's generator (SymPy sdm_monomial_lcm). */
export function sdmMonomialLcm(A: SdmMonomial, B: SdmMonomial): number[] {
  return [first(A), ...monomialLcm(A.slice(1), B.slice(1))];
}

/** Is there a polynomial monomial X with X*A = B (SymPy sdm_monomial_divides)? */
export function sdmMonomialDivides(A: SdmMonomial, B: SdmMonomial): boolean {
  return first(A) === first(B) && A.slice(1).every((a, i) => a <= at(B, i + 1));
}

/** The leading coefficient (zero for the zero element; SymPy sdm_LC). */
export function sdmLC(f: Sdm, K: Domain): unknown {
  return f.length ? first(f)[1] : K.zero;
}

/** The terms as a Map {monomial: coefficient} (SymPy sdm_to_dict). */
export function sdmToDict(f: Sdm): Map<SdmMonomial, unknown> {
  return new Map(f.map(([m, c]) => [m, c]));
}

/** The terms sorted by O, largest first (SymPy sdm_sort). */
export function sdmSort(f: Sdm, O: SdmOrder): SdmTerm[] {
  const key = keyOf(O);
  return [...f].sort((a, b) => compareMonomialKeys(key(b[0]), key(a[0])));
}

/** The terms with nonzero coefficients (SymPy sdm_strip). */
export function sdmStrip(f: Sdm): SdmTerm[] {
  return f.filter(([, c]) => !groundIsZero(c));
}

/** The element of the terms of a Map {monomial: coefficient} (SymPy sdm_from_dict). */
export function sdmFromDict(d: ReadonlyMap<SdmMonomial, unknown>, O: SdmOrder): SdmTerm[] {
  return sdmStrip(sdmSort([...d], O));
}

/** f + g (SymPy sdm_add). */
export function sdmAdd(f: Sdm, g: Sdm, O: SdmOrder, K: Domain): SdmTerm[] {
  const h = new Map<string, [SdmMonomial, unknown]>(f.map(([m, c]) => [mkey(m), [m, c]]));
  for (const [monom, c] of g) {
    const old = h.get(mkey(monom));
    if (old === undefined) {
      h.set(mkey(monom), [monom, c]);
      continue;
    }
    const coeff = domainArith(K, 'add', old[1], c);
    if (groundIsZero(coeff)) h.delete(mkey(monom));
    else h.set(mkey(monom), [old[0], coeff]);
  }
  return sdmFromDict(new Map(h.values()), O);
}

/** The leading monomial of a nonzero element (SymPy sdm_LM). */
export function sdmLM(f: Sdm): SdmMonomial {
  return first(f)[0];
}

/** The leading term of a nonzero element (SymPy sdm_LT). */
export function sdmLT(f: Sdm): SdmTerm {
  return first(f);
}

/** f times the polynomial term [X, c] (SymPy sdm_mul_term). */
export function sdmMulTerm(f: Sdm, term: readonly [readonly number[], unknown], _O: SdmOrder, K: Domain): SdmTerm[] {
  const [X, c] = term;
  if (!f.length || groundIsZero(c)) return [];
  if (K.isOne(K.toSympy(K.convert(c)))) return f.map(([M, fc]) => [sdmMonomialMul(M, X), fc]);
  return f.map(([M, fc]) => [sdmMonomialMul(M, X), domainArith(K, 'mul', fc, c)]);
}

/** The zero element (SymPy sdm_zero). */
export function sdmZero(): SdmTerm[] {
  return [];
}

/** The largest total degree of the terms of a nonzero element (SymPy sdm_deg). */
export function sdmDeg(f: Sdm): number {
  return Math.max(...f.map(([M]) => sdmMonomialDeg(M)));
}

/** The generators of the expanded polynomial components (SymPy parallel_dict_from_expr): the factors that are not numbers. */
function vectorGens(vec: readonly Expr[]): Expr[] {
  const gens = new Map<string, Expr>();
  for (const e of vec) {
    for (const t of e instanceof Add ? e.args : [e]) {
      for (const f of t instanceof Mul ? t.args : [t]) {
        const b = f instanceof Pow ? f.base : f;
        if (!(b instanceof Rational || b instanceof Float)) gens.set(b.key, b);
      }
    }
  }
  return sortGens([...gens.values()]);
}

/** The terms [exponents, coefficient] of an expanded polynomial in gens. */
function polyDict(e: Expr, gens: readonly Expr[]): [number[], Expr][] {
  const out = new Map<string, [number[], Expr]>();
  for (const t of e instanceof Add ? e.args : [e]) {
    const monom = gens.map(() => 0);
    const rest: Expr[] = [];
    for (const f of t instanceof Mul ? t.args : [t]) {
      const [b, k] = f instanceof Pow && f.exp instanceof Rational ? [f.base, Number(f.exp.p)] : [f, 1];
      const i = gens.findIndex((g) => g.key === b.key);
      if (i >= 0) monom[i] = at(monom, i) + k;
      else rest.push(f);
    }
    const old = out.get(mkey(monom));
    out.set(mkey(monom), [monom, old === undefined ? mul(...rest) : add(old[1], mul(...rest))]);
  }
  return [...out.values()];
}

/** The element of a vector of polynomial expressions (SymPy sdm_from_vector). */
export function sdmFromVector(vecIn: readonly Expr[], O: SdmOrder, K: Domain, opts: { gens?: readonly Expr[] } = {}): SdmTerm[] {
  const vec = vecIn.map((v) => expand(sympify(v)));
  const gens = opts.gens ?? vectorGens(vec);
  const dic = new Map<SdmMonomial, unknown>();
  vec.forEach((v, i) => {
    for (const [k, c] of polyDict(v, gens)) dic.set([i, ...k], K.convert(c));
  });
  return sdmFromDict(dic, O);
}

/** The vector of polynomial expressions of an element, of length n (SymPy sdm_to_vector). */
export function sdmToVector(f: Sdm, gens: readonly Expr[], K: Domain, n?: number): Expr[] {
  const dics = new Map<number, SdmTerm[]>();
  for (const [k, v] of f) dics.set(first(k), [...(dics.get(first(k)) ?? []), [k.slice(1), v]]);
  const len = n ?? dics.size;
  return Array.from({ length: len }, (_, k) =>
    add(...(dics.get(k) ?? []).map(([m, c]) => mul(K.toSympy(c), ...m.map((e, i) => pow(at(gens, i), e))))),
  );
}

/** The S-polynomial of f and g, or [S(f, g), the same combination of the phantom pair] (SymPy sdm_spoly). */
export function sdmSpoly(f: Sdm, g: Sdm, O: SdmOrder, K: Domain): SdmTerm[];
export function sdmSpoly(f: Sdm, g: Sdm, O: SdmOrder, K: Domain, phantom: readonly [Sdm, Sdm]): [SdmTerm[], SdmTerm[]];
export function sdmSpoly(f: Sdm, g: Sdm, O: SdmOrder, K: Domain, phantom?: readonly [Sdm, Sdm]): SdmTerm[] | [SdmTerm[], SdmTerm[]] {
  const zero = (): SdmTerm[] | [SdmTerm[], SdmTerm[]] => (phantom === undefined ? sdmZero() : [sdmZero(), sdmZero()]);
  if (!f.length || !g.length) return zero();
  const [LM1, LM2] = [sdmLM(f), sdmLM(g)];
  if (first(LM1) !== first(LM2)) return zero();
  const lcm = monomialLcm(LM1.slice(1), LM2.slice(1));
  const m1 = lcm.map((e, i) => e - at(LM1, i + 1));
  const m2 = lcm.map((e, i) => e - at(LM2, i + 1));
  const c = domainArith(K, 'quo', domainArith(K, 'sub', 0, sdmLC(f, K)), sdmLC(g, K));
  const one = K.convert(1);
  const r1 = sdmAdd(sdmMulTerm(f, [m1, one], O, K), sdmMulTerm(g, [m2, c], O, K), O, K);
  if (phantom === undefined) return r1;
  return [r1, sdmAdd(sdmMulTerm(phantom[0], [m1, one], O, K), sdmMulTerm(phantom[1], [m2, c], O, K), O, K)];
}

/** sdm_deg(f) - the degree of the leading monomial (SymPy sdm_ecart). */
export function sdmEcart(f: Sdm): number {
  return sdmDeg(f) - sdmMonomialDeg(sdmLM(f));
}

/** A normal form function (sdmNfMora, sdmNfBuchberger). */
export type SdmNormalForm = {
  (f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain): SdmTerm[];
  (f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain, phantom: readonly [Sdm, readonly Sdm[]]): [SdmTerm[], SdmTerm[]];
};

/** A weak normal form of f with respect to G by the generalized Mora algorithm (any order; SymPy sdm_nf_mora). */
export function sdmNfMora(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain): SdmTerm[];
export function sdmNfMora(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain, phantom: readonly [Sdm, readonly Sdm[]]): [SdmTerm[], SdmTerm[]];
export function sdmNfMora(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain, phantom?: readonly [Sdm, readonly Sdm[]]): SdmTerm[] | [SdmTerm[], SdmTerm[]] {
  let h: SdmTerm[] = [...f];
  let hp: SdmTerm[] = phantom === undefined ? [] : [...phantom[0]];
  const T: Sdm[] = [...G];
  const Tp: Sdm[] = phantom === undefined ? G.map(() => []) : [...phantom[1]];
  while (h.length) {
    const Th = T.map((g, i) => [g, sdmEcart(g), at(Tp, i)] as const).filter(([g]) => sdmMonomialDivides(sdmLM(g), sdmLM(h)));
    if (!Th.length) break;
    const [g, , gp] = Th.reduce((a, b) => (b[1] < a[1] ? b : a));
    if (sdmEcart(g) > sdmEcart(h)) {
      T.push(h);
      Tp.push(hp);
    }
    if (phantom === undefined) h = sdmSpoly(h, g, O, K);
    else [h, hp] = sdmSpoly(h, g, O, K, [hp, gp]);
  }
  return phantom === undefined ? h : [h, hp];
}

/** A weak normal form of f with respect to G by Buchberger's algorithm (global orders; SymPy sdm_nf_buchberger). */
export function sdmNfBuchberger(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain): SdmTerm[];
export function sdmNfBuchberger(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain, phantom: readonly [Sdm, readonly Sdm[]]): [SdmTerm[], SdmTerm[]];
export function sdmNfBuchberger(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain, phantom?: readonly [Sdm, readonly Sdm[]]): SdmTerm[] | [SdmTerm[], SdmTerm[]] {
  let h: SdmTerm[] = [...f];
  let hp: SdmTerm[] = phantom === undefined ? [] : [...phantom[0]];
  const Tp: readonly Sdm[] = phantom === undefined ? G.map(() => []) : phantom[1];
  while (h.length) {
    const i = G.findIndex((g) => sdmMonomialDivides(sdmLM(g), sdmLM(h)));
    if (i < 0) break;
    if (phantom === undefined) h = sdmSpoly(h, at(G, i), O, K);
    else [h, hp] = sdmSpoly(h, at(G, i), O, K, [hp, at(Tp, i)]);
  }
  return phantom === undefined ? h : [h, hp];
}

/** The reduced normal form of f with respect to G (global orders; SymPy sdm_nf_buchberger_reduced). */
export function sdmNfBuchbergerReduced(f: Sdm, G: readonly Sdm[], O: SdmOrder, K: Domain): SdmTerm[] {
  let h = sdmZero();
  let g: SdmTerm[] = [...f];
  while (g.length) {
    g = sdmNfBuchberger(g, G, O, K);
    if (g.length) {
      h = sdmAdd(h, [sdmLT(g)], O, K);
      g = g.slice(1);
    }
  }
  return h;
}

type Pair = readonly [number, number, number, readonly number[]];

/**
 * A minimal standard basis of G with respect to O, using the normal form NF
 * and the sugar strategy (SymPy sdm_groebner); with `extended`, also the
 * coefficient vectors expressing the basis in terms of G.
 */
export function sdmGroebner(G: readonly Sdm[], NF: SdmNormalForm, O: SdmOrder, K: Domain, extended?: false): SdmTerm[][];
export function sdmGroebner(G: readonly Sdm[], NF: SdmNormalForm, O: SdmOrder, K: Domain, extended: true): [SdmTerm[][], SdmTerm[][]];
export function sdmGroebner(G: readonly Sdm[], NF: SdmNormalForm, O: SdmOrder, K: Domain, extended = false): SdmTerm[][] | [SdmTerm[][], SdmTerm[][]] {
  const key = keyOf(O);
  let P: Pair[] = [];
  const S: Sdm[] = [];
  const Sugars: number[] = [];
  const Ssugar = (i: number, j: number): number => {
    const [LMi, LMj] = [sdmLM(at(S, i)), sdmLM(at(S, j))];
    return Math.max(at(Sugars, i) - sdmMonomialDeg(LMi), at(Sugars, j) - sdmMonomialDeg(LMj)) + sdmMonomialDeg(sdmMonomialLcm(LMi, LMj));
  };
  // (sugar, O(lcm), j), compared like Python tuples
  const ourcmp = (p: Pair, q: Pair): number => p[2] - q[2] || compareMonomialKeys(key(p[3]), key(q[3])) || p[1] - q[1];
  const update = (f: Sdm, sugar: number, Pin: Pair[]): Pair[] => {
    if (!f.length) return Pin;
    const k = S.length;
    S.push(f);
    Sugars.push(sugar);
    const LMf = sdmLM(f);
    const same = (a: readonly number[], b: readonly number[]): boolean => mkey(a) === mkey(b);
    const removethis = ([i, j, , t]: Pair): boolean => {
      if (first(LMf) !== first(t)) return false;
      const tik = sdmMonomialLcm(LMf, sdmLM(at(S, i)));
      const tjk = sdmMonomialLcm(LMf, sdmLM(at(S, j)));
      return !same(tik, t) && !same(tjk, t) && sdmMonomialDivides(tik, t) && sdmMonomialDivides(tjk, t);
    };
    const Pk = Pin.filter((p) => !removethis(p));
    const N: Pair[] = [];
    for (let i = 0; i < k; i++) if (first(LMf) === first(sdmLM(at(S, i)))) N.push([i, k, Ssugar(i, k), sdmMonomialLcm(LMf, sdmLM(at(S, i)))]);
    N.sort(ourcmp);
    const remove = new Set<number>();
    N.forEach((p, i) => {
      for (let j = i + 1; j < N.length; j++) if (sdmMonomialDivides(p[3], at(N, j)[3])) remove.add(j);
    });
    Pk.push(...N.filter((_p, i) => !remove.has(i)).reverse());
    // reverse-sorted: the pairs are popped from the end
    return Pk.sort((p, q) => ourcmp(q, p));
  };
  const firstNonzero = G.find((x) => x.length);
  if (firstNonzero === undefined) return extended ? [[], []] : [];
  const numgens = first(firstNonzero)[0].length - 1;
  const coefficients: Sdm[] = [];
  G.forEach((f, i) => {
    P = update(f, f.length ? sdmDeg(f) : 0, P);
    if (extended && f.length) coefficients.push(sdmFromDict(new Map([[[i, ...Array.from({ length: numgens }, () => 0)], K.convert(1)]]), O));
  });
  while (P.length) {
    const [i, j] = defined(P.pop());
    const [f, g] = [at(S, i), at(S, j)];
    if (extended) {
      const [sp, coeff] = sdmSpoly(f, g, O, K, [at(coefficients, i), at(coefficients, j)]);
      const [h, hcoeff] = NF(sp, S, O, K, [coeff, coefficients]);
      if (h.length) coefficients.push(hcoeff);
      P = update(h, Ssugar(i, j), P);
    } else P = update(NF(sdmSpoly(f, g, O, K), S, O, K), Ssugar(i, j), P);
  }
  // interreduce: drop the elements whose leading monomial is divisible by another's
  let Sset = S.map((f, i) => [f, i] as const);
  for (const [a, ai] of [...Sset]) {
    for (const [b, bi] of [...Sset]) {
      if (ai === bi || !Sset.some(([, x]) => x === ai) || !Sset.some(([, x]) => x === bi)) continue;
      if (sdmMonomialDivides(sdmLM(a), sdmLM(b))) Sset = Sset.filter(([, x]) => x !== bi);
    }
  }
  const L = [...Sset].sort((p, q) => compareMonomialKeys(key(sdmLM(q[0])), key(sdmLM(p[0]))));
  const res = L.map(([f]) => [...f]);
  if (extended) return [res, L.map(([, i]) => [...at(coefficients, i)])];
  return res;
}
